out['completed_at']=now();(base/'固定原期标题查询首次取得回执.json').write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf-8')
p=out.get('payload',{});print('固定原期实际标题查询',out['status'],'命中',p.get('totalHits') if isinstance(p,dict) else None,flush=True)
if isinstance(p,dict):
 for d in p.get('resultDocs',[]):print(d.get('data',{}).get('titleO'),d.get('data',{}).get('url'),flush=True)
